import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { STATIC } from "../src/ui/assets.ts";

// Bastion's files are generated by scripts/mascot/export.mjs; the dashboard and the Mac app
// both trust the manifest to slice the strips, so the two must agree.
const dir = new URL("../src/ui/static/mascot/", import.meta.url);
const manifest = JSON.parse(readFileSync(new URL("manifest.json", dir), "utf8")) as {
  fps: number;
  scenes: Record<string, { frames: number; x: number; y: number; width: number; height: number; durationMs: number }>;
};

const pngSize = (buf: Buffer) => ({ width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) });

test("every mascot scene's strip matches its manifest entry and is served", () => {
  assert.deepEqual(Object.keys(manifest.scenes).sort(), ["crit", "fixed", "high", "idle", "mal"]);
  for (const [name, s] of Object.entries(manifest.scenes)) {
    const size = pngSize(readFileSync(new URL(`${name}.png`, dir)));
    assert.deepEqual(size, { width: s.width * s.frames, height: s.height }, name);
    assert.ok(s.x >= 0 && s.y >= 0 && s.x + s.width <= 120 && s.y + s.height <= 68, `${name} fits the 120x68 stage`);
    assert.equal(s.durationMs, Math.round((s.frames * 1000) / manifest.fps), name);
    assert.ok(`/mascot/${name}.png` in STATIC, `${name} is in the dashboard allowlist`);
  }
  assert.ok("/mascot/manifest.json" in STATIC);
});

test("the Mac app has every menu bar helmet it asks for, at 1x and 2x", () => {
  const mac = new URL("../macos/Resources/mascot/", import.meta.url);
  for (const name of ["watch", "sleep", "high", "crit", "mal"]) {
    const one = new URL(`menubar-${name}.png`, mac);
    const two = new URL(`menubar-${name}@2x.png`, mac);
    assert.ok(existsSync(one) && existsSync(two), name);
    const a = pngSize(readFileSync(one));
    assert.deepEqual(pngSize(readFileSync(two)), { width: a.width * 2, height: a.height * 2 }, name);
  }
});
